         int size = getSize(head);
        ListNode ohead = null;
        ListNode otail = null;
        ListNode temp = head;
        while(size>=k){
            int K = k;

            while(K-->0){
                ListNode next = temp.next;
                temp.next = null;
                addFirst(temp);
                temp = next;
                size--;
            }
            if(ohead == null){
                ohead = thead;
                otail = ttail;
